[
  {
    "statement": "There is limited evidence specifically about cost-effective methods for reducing human-primate conflict in agricultural areas.",
    "citations": []
  },
  {
    "statement": "There is no evidence from systematic studies evaluating the effectiveness of using unpalatable buffer crops as a primate-specific deterrent.",
    "citations": [
      "1438"
    ]
  },
  {
    "statement": "There is no evidence from systematic studies evaluating the effectiveness of mechanical barriers like fences and ditches as a primate-specific deterrent.",
    "citations": [
      "1436"
    ]
  },
  {
    "statement": "There is no evidence from systematic studies evaluating the effectiveness of paying farmers to cover costs of non-harmful deterrent strategies.",
    "citations": [
      "1429"
    ]
  },
  {
    "statement": "There is no evidence from systematic studies evaluating the effectiveness of planting crops favoured by primates away from primate areas.",
    "citations": [
      "1440"
    ]
  },
  {
    "statement": "There is no evidence from systematic studies evaluating the effectiveness of compensating farmers for produce loss.",
    "citations": [
      "1428"
    ]
  },
  {
    "statement": "Some general mammal deterrent methods that could apply to primates show evidence of effectiveness.",
    "citations": []
  },
  {
    "statement": "Using chili-based deterrents showed mixed results as a mammal deterrent.",
    "citations": [
      "2492"
    ]
  },
  {
    "statement": "Chili-spray, chili smoke, chili fences and chili extract have been found to repel elephants, at least initially.",
    "citations": [
      "2492"
    ]
  },
  {
    "statement": "Some studies found chili smoke and chili fences did not reduce crop raiding.",
    "citations": [
      "2492"
    ]
  },
  {
    "statement": "Using loud noises as a deterrent showed variable effectiveness.",
    "citations": [
      "2460"
    ]
  },
  {
    "statement": "Loud noises activated when animals were in the vicinity reduced crop damage by deer and elephants.",
    "citations": [
      "2460"
    ]
  },
  {
    "statement": "Regularly sounding loud noises did not repel rabbits or deer.",
    "citations": [
      "2460"
    ]
  },
  {
    "statement": "Fire deterrents showed some effectiveness in reducing crop damage.",
    "citations": [
      "2499"
    ]
  },
  {
    "statement": "Studies found fire reduced crop damage by elephants.",
    "citations": [
      "2499"
    ]
  },
  {
    "statement": "Large fires combined with people and drums repelled elephants faster than other combinations.",
    "citations": [
      "2499"
    ]
  },
  {
    "statement": "Drones showed promise as a deterrent for large mammals.",
    "citations": [
      "2481"
    ]
  },
  {
    "statement": "Drones were found to repel elephants from crops within one minute.",
    "citations": [
      "2481"
    ]
  }
]

[
  {
    "statement": "Primate reintroduction success rates show considerable variation by region.",
    "citations": []
  },
  {
    "statement": "In Africa, chimpanzee reintroduction programs demonstrated mixed results.",
    "citations": []
  },
  {
    "statement": "In Guinea and the Republic of Congo, the majority of reintroduced chimpanzees survived for 1-5 years.",
    "citations": [
      "1591"
    ]
  },
  {
    "statement": "In The Gambia, a reintroduced chimpanzee population increased by 38% over 25 years.",
    "citations": [
      "1597"
    ]
  },
  {
    "statement": "In another case in The Gambia, a reintroduced chimpanzee population increased 25 years after reintroduction.",
    "citations": [
      "1567"
    ]
  },
  {
    "statement": "Western gorilla programs in Gabon and the Republic of Congo showed that the majority of the gorillas survived for at least 9 months to 4 years.",
    "citations": [
      "1567",
      "1595"
    ]
  },
  {
    "statement": "In Indonesian studies, all Sumatran orangutans survived for at least 3 months after reintroduction.",
    "citations": [
      "1567",
      "1590"
    ]
  },
  {
    "statement": "In one Malaysian study, orangutan populations showed 98% survival after release.",
    "citations": [
      "1589"
    ]
  },
  {
    "statement": "In another Malaysian study, an orangutan population showed a decline of 33% over 33 years.",
    "citations": [
      "1591",
      "1597"
    ]
  },
  {
    "statement": "In South America, Brazilian studies on primate reintroduction showed mixed outcomes.",
    "citations": []
  },
  {
    "statement": "Golden lion tamarin programs in Brazil reported that most reintroduced individuals did not survive over 7 years.",
    "citations": [
      "1594",
      "1597"
    ]
  },
  {
    "statement": "Other Brazilian studies found that golden lion tamarin populations declined after reintroduction.",
    "citations": [
      "1567",
      "1589"
    ]
  },
  {
    "statement": "In Madagascar, studies found that primate populations persisted 4-55 years after reintroduction.",
    "citations": [
      "1567"
    ]
  },
  {
    "statement": "In Madagascar, most black-and-white ruffed lemurs with limited free-ranging experience died over 5 years.",
    "citations": [
      "1595"
    ]
  },
  {
    "statement": "In Belize, primate reintroduction recorded population increases 5 years after reintroduction.",
    "citations": [
      "1567",
      "1591"
    ]
  },
  {
    "statement": "Thailand showed primate population declines post-reintroduction.",
    "citations": [
      "1567",
      "1590"
    ]
  },
  {
    "statement": "African studies generally showed higher long-term survival rates for great apes.",
    "citations": []
  },
  {
    "statement": "Asian orangutan programs showed variable results.",
    "citations": []
  },
  {
    "statement": "South American primate reintroduction programs had more mixed outcomes.",
    "citations": []
  }
]

[
  {
    "statement": "No studies were found that directly evaluate the impact of plastic pollution in waterways on primate populations that live near rivers.",
    "citations": []
  },
  {
    "statement": "A search revealed several related actions, including the removal of debris from freshwater marshes, freshwater swamps, and brackish/saline swamps.",
    "citations": [
      "3161",
      "3163",
      "3164"
    ]
  },
  {
    "statement": "No studies have been found that evaluate the effects of debris removal on vegetation.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effects on marine and freshwater mammal populations from limiting the discharge of solid waste overboard from vessels.",
    "citations": [
      "2893",
      "2202"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects on benthic invertebrate populations from limiting the discharge of solid waste overboard from vessels.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the effects on marine and freshwater mammal populations from removing and cleaning up shoreline waste disposal sites.",
    "citations": [
      "2909"
    ]
  },
  {
    "statement": "Actions related to primate management include installing primate-proof garbage bins.",
    "citations": [
      "1505"
    ]
  },
  {
    "statement": "No evidence was found for the effects of installing primate-proof garbage bins on primate populations.",
    "citations": []
  },
  {
    "statement": "The specific intersection of plastic pollution in waterways and impacts on riverine primate populations has not been systematically studied according to database searches.",
    "citations": []
  }
]
